import { sha256 } from "../../../primitives/sha256.js";
import { encodedLiteral, projectionFile } from "../rendering.js";
function snakeCase(value) {
    return value.replace(/([a-z0-9])([A-Z])/g, "$1_$2").toLowerCase();
}
function renderObject(definition) {
    const dependencies = new Set(definition.fields.flatMap((field) => field.dependencies));
    dependencies.delete(definition.typeName);
    const imports = [...dependencies].sort().map((dependency) => `from .${snakeCase(dependency)} import ${dependency}`).join("\n");
    const needsLiteral = definition.constants.length > 0;
    const constants = definition.constants.map((constant) => `${constant.name}: Literal[${encodedLiteral("python", constant.value)}] = ${encodedLiteral("python", constant.value)}`).join("\n");
    const fields = definition.fields.map((field) => `    ${field.name}: ${field.type}${field.defaultLiteral === undefined ? "" : ` = ${field.defaultLiteral}`}`).join("\n");
    return `"""Projected from kernel/schemas/${definition.sourcePointer.replace(/#$/, "").replace("#/properties/", "/properties/")}.\n` +
        "GENERATED by tools/src/projection/providers/python/structural-projection-provider.ts — do not hand-edit.\n\"\"\"\n\n" +
        "from __future__ import annotations\n\n" +
        (needsLiteral ? "from typing import Literal\n\n" : "") +
        "from dataclasses import dataclass\n" +
        (imports ? `${imports}\n` : "") + "\n" +
        (constants ? `${constants}\n\n\n` : "") +
        `@dataclass(frozen=True)\nclass ${definition.typeName}:\n${fields}\n`;
}
function render(definition) {
    if (definition.kind === "enum") {
        return `"""Projected from kernel/schemas/${definition.sourcePointer.replace(/#$/, "").replace("#/properties/", "/properties/")}.\n` +
            "GENERATED by tools/src/projection/providers/python/structural-projection-provider.ts — do not hand-edit.\n\"\"\"\n\n" +
            "from __future__ import annotations\n\nfrom typing import Literal\n\n" +
            `${definition.typeName} = Literal[${definition.values.map((value) => encodedLiteral("python", value)).join(", ")}]\n`;
    }
    return renderObject(definition);
}
export class PythonStructuralProjectionProvider {
    target = "python";
    render(graph, profile) {
        if (graph.target !== this.target || profile.language !== this.target)
            throw new Error("Python renderer received another target.");
        const files = graph.definitions.map((definition) => projectionFile(`${snakeCase(definition.typeName)}.py`, render(definition), definition));
        const imports = graph.definitions.map((definition) => {
            const names = [definition.typeName, ...(definition.kind === "object" ? definition.constants.map((constant) => constant.name) : [])];
            return `from .${snakeCase(definition.typeName)} import ${names.join(", ")}`;
        });
        const exportedNames = graph.definitions.flatMap((definition) => [
            definition.typeName,
            ...(definition.kind === "object" ? definition.constants.map((constant) => constant.name) : [])
        ]);
        const init = "\"\"\"Scenario Kernel canonical contract types, projected from kernel/schemas/.\n\n" +
            "GENERATED by tools/src/projection/providers/python/structural-projection-provider.ts — do not hand-edit.\n\"\"\"\n\n" +
            `${imports.join("\n")}\n\n__all__ = [\n${exportedNames.map((name) => `    ${JSON.stringify(name)},`).join("\n")}\n]\n`;
        files.push({
            relativePath: "__init__.py",
            content: init,
            digest: sha256(init),
            sourcePointers: graph.definitions.map((definition) => definition.sourcePointer)
        });
        return {
            planType: "projection-plan.v1",
            target: this.target,
            outputDirectory: profile.outputDirectory,
            files
        };
    }
}
